const ids = [...usClean, ...frontierScan].map((p) => p.id);
const dups = ids.filter((id, i) => ids.indexOf(id) !== i);
if (dups.length) {
  console.error("dup ids", dups);
  process.exit(1);
}

const existingUs = [
  ...JSON.parse(readFileSync(join(root, "src/data/parks.json"), "utf8")),
  ...JSON.parse(readFileSync(join(root, "src/data/us-parks.json"), "utf8")),
].map((p) => p.id);
const clashUs = usClean.filter((p) => existingUs.includes(p.id)).map((p) => p.id);
if (clashUs.length) {
  console.error("nationwide id clash with existing catalog", clashUs);
  process.exit(1);
}

const existingF9 = [
  ...JSON.parse(readFileSync(join(root, "src/data/frontier-parks.json"), "utf8")),
  ...JSON.parse(readFileSync(join(root, "src/data/frontier-more.json"), "utf8")),
].map((p) => p.id);
const clashF9 = frontierScan.filter((p) => existingF9.includes(p.id)).map((p) => p.id);
if (clashF9.length) {
  console.error("frontier id clash with existing catalog", clashF9);
  process.exit(1);
}

writeFileSync(join(root, "src/data/us-market.json"), JSON.stringify(usClean, null, 2) + "\n");
writeFileSync(join(root, "src/data/frontier-scan.json"), JSON.stringify(frontierScan, null, 2) + "\n");
console.log("nationwide extra", usClean.length, "states", new Set(usClean.map((p) => p.state)).size);
console.log("frontier extra", frontierScan.length, "hubs", new Set(frontierScan.map((p) => p.hub)).size);
